ValidationRule.errorConditionFormula:
AND(
    NOT(ISBLANK(AccountId)),

    NOT(
        OR(
            RecordTypeName__c = "DairyProducts",
            RecordTypeName__c = "PHOCSDairyPlantRoomsandEquipment"
        )
    ),

    NOT(
        OR(
            /* Child Care */
            AND(
                Account.RecordTypeName__c = "Facility",
                TEXT(Account.Type) = "Child Care",
                RecordTypeName__c = "ChildCareService"
            ),

            /* Drinking Water */
            AND(
                Account.RecordTypeName__c = "DrinkingWaterSystem",
                TEXT(Account.Type) = "Drinking Water",
                RecordTypeName__c = "PHOCSDrinkingWaterSystemComponent"
            ),

            /* Personal Services */
            AND(
                Account.RecordTypeName__c = "Facility",
                TEXT(Account.Type) = "Personal Services",
                RecordTypeName__c = "PHOCSPersonalServices"
            ),

            /* Recreational Water */
            AND(
                Account.RecordTypeName__c = "Facility",
                TEXT(Account.Type) = "Recreational Water",
                RecordTypeName__c = "PHOCSRecreationalWater"
            ),

            /* Residential Care */
            AND(
                Account.RecordTypeName__c = "Facility",
                TEXT(Account.Type) = "Residential Care",
                RecordTypeName__c = "ResidentialCareService"
            ),

            /* Industrial Camps */
            AND(
                Account.RecordTypeName__c = "Facility",
                TEXT(Account.Type) = "Industrial Camps",
                RecordTypeName__c = "PHOCS_Sewerage_Component"
            )
        )
    )
)
